package com.bank.neft.service;

import com.bank.neft.dto.*;
import com.bank.neft.model.Account;
import com.bank.neft.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class NeftTransferService {

    private final AccountRepository accountRepo;

    /**
     * @Transactional: the AOP proxy wraps this method.
     *
     * WHAT THE PROXY DOES:
     * 1. Gets a connection from HikariCP pool
     * 2. Sets connection.setAutoCommit(false) → BEGIN TRANSACTION
     * 3. Binds connection to current thread (TransactionSynchronizationManager)
     * 4. Calls THIS real method
     * 5a. On success → connection.commit()
     * 5b. On RuntimeException → connection.rollback()
     * 5c. On CHECKED exception → connection.commit() (DEFAULT! Fix with rollbackFor)
     * 6. Returns connection to pool
     *
     * KEY ATTRIBUTES DEMONSTRATED:
     * - isolation: READ_COMMITTED (only see committed data from other TX)
     * - rollbackFor: Exception.class (rollback on checked exceptions too)
     * - timeout: 10 seconds (fail if TX takes longer)
     */
    @Transactional(
        isolation = Isolation.READ_COMMITTED,
        rollbackFor = Exception.class,
        timeout = 10
    )
    public NeftResponse transfer(NeftRequest request) {
        String transferId = "NEFT-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();
        log.info("NEFT {}: Rs.{} from {} to {}", transferId, request.amount(),
            request.fromAccountId(), request.toAccountId());

        // Both queries use the SAME connection (bound to thread by proxy)
        Account from = accountRepo.findByIdForUpdate(request.fromAccountId())
            .orElseThrow(() -> new IllegalArgumentException("Account not found: " + request.fromAccountId()));

        Account to = accountRepo.findByIdForUpdate(request.toAccountId())
            .orElseThrow(() -> new IllegalArgumentException("Account not found: " + request.toAccountId()));

        // If credit throws (frozen account) → proxy catches RuntimeException → ROLLBACK
        // The debit is also undone — atomicity!
        from.debit(request.amount());
        to.credit(request.amount());  // throws if account is FROZEN

        accountRepo.save(from);
        accountRepo.save(to);

        log.info("NEFT {} completed: {} balance={}, {} balance={}",
            transferId, from.getAccountId(), from.getBalance(),
            to.getAccountId(), to.getBalance());

        return new NeftResponse(transferId, request.fromAccountId(), request.toAccountId(),
            request.amount(), "COMPLETED", from.getBalance(), to.getBalance());
    }
}
