package com.bank.neft.service;

import com.bank.neft.dto.*;
import com.bank.neft.model.Account;
import com.bank.neft.repository.AccountRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class NeftTransferServiceTest {

    @Mock AccountRepository accountRepo;
    @InjectMocks NeftTransferService transferService;

    @Test
    void shouldTransferSuccessfully() {
        Account from = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account to = new Account("CUR3001", "Priya", new BigDecimal("250000"));
        when(accountRepo.findByIdForUpdate("SAV2001")).thenReturn(Optional.of(from));
        when(accountRepo.findByIdForUpdate("CUR3001")).thenReturn(Optional.of(to));
        when(accountRepo.save(any())).thenAnswer(i -> i.getArgument(0));

        NeftResponse response = transferService.transfer(
            new NeftRequest("SAV2001", "CUR3001", new BigDecimal("50000"), "Rent"));

        assertThat(response.status()).isEqualTo("COMPLETED");
        assertThat(response.fromBalance()).isEqualByComparingTo("950000");
        assertThat(response.toBalance()).isEqualByComparingTo("300000");
    }

    @Test
    void shouldRollbackWhenReceiverAccountFrozen() {
        Account from = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account frozen = new Account("FRZ4001", "Amit", new BigDecimal("500000"));
        // Simulate frozen account by directly setting status via reflection or test builder
        when(accountRepo.findByIdForUpdate("SAV2001")).thenReturn(Optional.of(from));
        when(accountRepo.findByIdForUpdate("FRZ4001")).thenReturn(Optional.of(frozen));

        // credit() on frozen account throws → @Transactional proxy ROLLBACK → debit undone
        assertThatThrownBy(() -> transferService.transfer(
            new NeftRequest("SAV2001", "FRZ4001", new BigDecimal("50000"), null)))
            .isInstanceOf(IllegalStateException.class)
            .hasMessageContaining("FROZEN");
    }
}
